/// 整合包探测结果 (供 UI 预填默认值)
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DetectedRuntime {
    /// 是否为可用的整合包根目录
    pub valid: bool,
    /// 内置运行时路径
    pub embedded_python: Option<String>,
    /// 内置运行时是否存在
    pub has_embedded_python: bool,
    /// 控制脚本是否存在
    pub has_script: bool,
    /// 推理配置是否存在
    pub has_infer_config: bool,
    /// 探测到的问题 (供 UI 提示)
    pub issues: Vec<String>,
}

/// 探测整合包目录, 给出默认启动配置所需的全部信息
pub fn detect(root: &Path) -> DetectedRuntime {
    let mut issues = Vec::new();

    if !root.is_dir() {
        return DetectedRuntime {
            valid: false,
            embedded_python: None,
            has_embedded_python: false,
            has_script: false,
            has_infer_config: false,
            issues: vec!["目录不存在".into()],
        };
    }

    let embedded = root.join("runtime").join("python.exe");
    let has_embedded = embedded.is_file();
    if !has_embedded {
        issues.push(
            "未见整合包内置运行时 (runtime\\python.exe), 请指定外部 Python 或自定义命令".into(),
        );
    }

    let has_script = root.join(DEFAULT_SCRIPT).is_file();
    if !has_script {
        issues.push(format!("未见控制脚本 {DEFAULT_SCRIPT}"));
    }

    let has_infer_config = root.join(DEFAULT_INFER_CONFIG).is_file();
    if !has_infer_config {
        issues.push(format!("未见推理配置 {DEFAULT_INFER_CONFIG}"));
    }

    DetectedRuntime {
        valid: has_script,
        embedded_python: has_embedded.then(|| embedded.display().to_string()),
        has_embedded_python: has_embedded,
        has_script,
        has_infer_config,
        issues,
    }
}

/// 候选 GSOV 模型 (一整套 GPT + SoVITS 权重)
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ModelCandidate {
    /// 推断的角色名 (由权重文件名归一化而来)
    pub name: String,
    /// GPT (T2S) 权重路径, 相对整合包根, 正斜杠分隔
    pub gpt_weights: String,
    /// SoVITS 权重路径, 相对整合包根, 正斜杠分隔
    pub sovits_weights: String,
}

/// 扫描整合包内的权重目录, 推断出可用的模型组合。
///
/// GPT-SoVITS 的权重目录命名约定为 `GPT_weights[_vN]` 与 `SoVITS_weights[_vN]`,
/// 训练产物文件名通常是「角色名 + 训练步数字段」(如 `爱音-e15.ckpt` 与
/// `爱音_e4_s436_l64.pth`)。这里按**归一化后的公共前缀**配对, 只返回两边都存在的组合,
/// 因此不会给出无法使用的建议。仅支持 v4: `_v2` / `_v3` 目录会被跳过。
pub fn scan_models(root: &Path) -> Vec<ModelCandidate> {
    let debug = std::env::var("WEBGAL_INK_DEBUG_SCAN").is_ok();
    let mut gpt_files: Vec<(String, String)> = Vec::new(); // (归一化名, 相对路径)
    let mut sovits_files: Vec<(String, String)> = Vec::new();

    let top = read_dir_entries(root);
    if debug {
        eprintln!("[scan] root={} entries={}", root.display(), top.len());
    }

    for entry in top {
        let name = entry.file_name;
        let is_gpt = name.starts_with("GPT_weights");
        let is_sovits = name.starts_with("SoVITS_weights");
        if debug {
            eprintln!("[scan] name={name:?} gpt={is_gpt} sovits={is_sovits}");
        }
        let is_sovits = name.starts_with("SoVITS_weights");
        if !is_gpt && !is_sovits {
            continue;
        }
        // 仅 v4: 无版本后缀, 或后缀恰为 `_v4`; 显式跳过 v1/v2/v3 等旧版本目录
        if let Some((_, suffix)) = name.rsplit_once("_v") {
            if !suffix.is_empty() && suffix != "4" && suffix.chars().all(|ch| ch.is_ascii_digit()) {
                continue;
            }
        }

        for file in read_dir_entries(&root.join(&name)) {
            if !file.is_file {
                continue;
            }
            let extension = file
                .file_name
                .rsplit_once('.')
                .map(|(_, ext)| ext.to_ascii_lowercase())
                .unwrap_or_default();
            let expected = if is_gpt { "ckpt" } else { "pth" };
            if extension != expected {
                continue;
            }
            let relative = format!("{}/{}", name, file.file_name);
            let key = normalize_model_name(&file.file_name);
            if is_gpt {
                gpt_files.push((key, relative));
            } else {
                sovits_files.push((key, relative));
            }
        }
    }

    let mut candidates = Vec::new();
    for (gpt_key, gpt_weights) in &gpt_files {
        // 选取归一化名匹配度最高的 SoVITS 权重: 互为前缀即视为同一角色
        let best = sovits_files
            .iter()
            .filter(|(sovits_key, _)| {
                !sovits_key.is_empty()
                    && !gpt_key.is_empty()
                    && (gpt_key.starts_with(sovits_key.as_str())
                        || sovits_key.starts_with(gpt_key.as_str()))
            })
            .max_by_key(|(sovits_key, _)| sovits_key.len().min(gpt_key.len()));
        let Some((_, sovits_weights)) = best else {
            continue;
        };
        candidates.push(ModelCandidate {
            name: display_model_name(gpt_weights),
            gpt_weights: gpt_weights.clone(),
            sovits_weights: sovits_weights.clone(),
        });
    }

    candidates.sort_by(|a, b| a.name.cmp(&b.name));
    candidates
}

/// 去掉训练后缀与扩展名, 得到用于配对的归一化名
fn normalize_model_name(file_name: &str) -> String {
    let stem = file_name
        .rsplit_once('.')
        .map(|(stem, _)| stem)
        .unwrap_or(file_name);
    let mut result = String::new();
    for ch in stem.chars() {
        // 训练后缀形如 `-e15` / `_e4_s436_l64`, 遇到 `-` 或 `_` 即截断
        if ch == '-' || ch == '_' {
            break;
        }
        result.push(ch);
    }
    result.trim().to_lowercase()
}

/// 展示用名称: 权重文件的主干名
fn display_model_name(relative: &str) -> String {
    relative
        .rsplit('/')
        .next()
        .unwrap_or(relative)
        .rsplit_once('.')
        .map(|(stem, _)| stem)
        .unwrap_or(relative)
        .to_string()
}

/// 目录项
struct DirEntryName {
    file_name: String,
    is_file: bool,
}

fn read_dir_entries(dir: &Path) -> Vec<DirEntryName> {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return Vec::new();
    };
    entries
        .filter_map(Result::ok)
        .map(|entry| DirEntryName {
            file_name: entry.file_name().to_string_lossy().to_string(),
            is_file: entry
                .file_type()
                .map(|kind| kind.is_file())
                .unwrap_or(false),
        })
        .collect()
}

/// 按探测结果构造默认启动配置
pub fn default_config(root: &Path, detected: &DetectedRuntime) -> LaunchConfig {
    let mode = match &detected.embedded_python {
        Some(program) => LaunchMode::Embedded {
            program: program.clone(),
        },
        None => LaunchMode::Python {
            program: "python".into(),
        },
    };
    LaunchConfig {
        root: root.display().to_string(),
        mode,
        host: DEFAULT_HOST.into(),
        port: DEFAULT_PORT,
        script: DEFAULT_SCRIPT.into(),
        infer_config: DEFAULT_INFER_CONFIG.into(),
        extra_args: Vec::new(),
    }
}

/// 启动命令
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LaunchCommand {
    pub program: String,
    pub args: Vec<String>,
    pub cwd: PathBuf,
}

impl LaunchConfig {
    /// 拼装实际启动命令
    pub fn build_command(&self) -> LaunchCommand {
        let cwd = PathBuf::from(&self.root);
        let (program, mut args) = match &self.mode {
            LaunchMode::Embedded { program } | LaunchMode::Python { program } => {
                let mut args: Vec<String> = Vec::new();
                if self.mode.isolated() {
                    args.push("-I".into());
                }
                args.push(self.script.clone());
                args.push("-a".into());
                args.push(self.host.clone());
                args.push("-p".into());
                args.push(self.port.to_string());
                args.push("-c".into());
                args.push(self.infer_config.clone());
                args.extend(self.extra_args.iter().cloned());
                (program.clone(), args)
            }
            LaunchMode::Command { program, args } => (program.clone(), args.clone()),
        };
        args.shrink_to_fit();
        LaunchCommand { program, args, cwd }
    }
}

/// 用于日志面板的换行切分。
///
/// GSOV 依赖的 `tqdm` 进度条用 `\r` 覆盖同一行且**不换行**, 直接按 `\n` 收集会把
/// 整个推理过程的进度条拼成一条超长文本。这里按 `\n` / `\r` 任意一个切分, 并忽略空段。
#[derive(Debug, Default)]
pub struct LineSplitter {
    buffer: String,
}

impl LineSplitter {
    pub fn new() -> Self {
        Self::default()
    }

    /// 送入一段输出, 返回其中完整的行
    pub fn push(&mut self, chunk: &str) -> Vec<String> {
        let mut lines = Vec::new();
        for ch in chunk.chars() {
            match ch {
                '\n' | '\r' => {
                    let line = std::mem::take(&mut self.buffer);
                    let trimmed = line.trim();
                    if !trimmed.is_empty() {
                        lines.push(trimmed.to_string());
                    }
                }
                other => {
                    self.buffer.push(other);
                    // 防御性截断: 进度条可能极长且无分隔符
                    if self.buffer.len() > 4096 {
                        let line = std::mem::take(&mut self.buffer);
                        lines.push(line);
                    }
                }
            }
        }
        lines
    }

    /// 取走缓冲区中的残留内容 (进程结束时调用)
    pub fn flush(&mut self) -> Option<String> {
        let line = std::mem::take(&mut self.buffer);
        let trimmed = line.trim();
        (!trimmed.is_empty()).then(|| trimmed.to_string())
    }
}

