        touch(&root, "SoVITS_weights_v4/爱音_e4_s436_l64.pth");
        touch(&root, "GPT_weights_v4/素世(夹)-e15.ckpt");
        touch(&root, "SoVITS_weights_v4/素世(夹)_e4_s512_l64.pth");

